using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ResourceChecks {
 static void Require(bool valid,string reason){if(!valid)throw new Exception(reason);}
 [MenuItem("BWVR/Verify resource accounting")]
 public static void VerifyModel(){var state=new ResourceState();var source=state.Ensure("tree",VillageResource.Wood);Require(state.Harvest(0,"tree",3)==3&&source.remaining==9&&state.wood==0,"Harvest credited stores before delivery");Require(state.Harvest(0,"tree",3)==0,"Cargo harvested twice");var saved=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(state));Require(saved.Valid(),"Pending cargo save rejected");saved.Recover(0);Require(saved.Find("tree").remaining==12&&saved.wood==0,"Reload recovery lost or created wood");Require(state.Deposit(0)==3&&state.wood==3&&state.Deposit(0)==0&&state.deliveries==1,"Deposit not exactly once");state.Harvest(0,"tree",3);state.wood=36;Require(state.Deposit(0)==0&&source.remaining==9,"Capacity overflow lost cargo");state.Ensure("field",VillageResource.Wheat);Require(state.Harvest(2,"field",99)==3&&state.Valid(),"Oversized load exceeded cargo bounds");state.Recover(2);float grain=state.wheat;state.Consume(30,3);Require(Mathf.Abs(grain-state.wheat-1)<.001f,"Food consumption not based on stocks");Require(new SliceState().Valid(),"Legacy save rejected");var corrupt=new SliceState{resources=state};state.cargo[0].amount=float.NaN;Require(!corrupt.Valid(),"Invalid cargo accepted");Debug.Log("BWVR_RESOURCE_MODEL_PASS: finite harvest; pending cargo; exactly-once delivery; capacity; recovery; food consumption; legacy/corrupt saves");}
 [MenuItem("BWVR/Verify native resource gathering (Play mode)")]
 public static void VerifyRuntime(){var world=UnityEngine.Object.FindAnyObjectByType<VillageResources>();Require(EditorApplication.isPlaying&&world!=null,"Enter Play mode first");var slice=world.GetComponentInParent<QuestSlice>();var field=typeof(QuestSlice).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance);var original=(SliceState)field.GetValue(slice);var god=slice.GetComponentInChildren<CreatureHybrid>();god.Interrupt("Resource QA");var actors=world.Gatherers;var positions=actors.Select(a=>a.transform.position).ToArray();foreach(var actor in actors){actor.Cancel();actor.GetComponent<VillagerSocial>().ResetTask();actor.GetComponent<VillagerExploration>().ResetTask();actor.GetComponent<VillagerBlockPlay>().ResetTask();}var test=new SliceState{developmentFocus=true};field.SetValue(slice,test);world.ResetWorld();
  try{Require(world.sources.Any(s=>s.kind==VillageResource.Wood)&&world.sources.Any(s=>s.kind==VillageResource.Wheat),"Missing finite wood/wheat sources");var wood=world.sources.First(s=>s.kind==VillageResource.Wood&&world.Available(s));var actor=actors[1];var nav=actor.GetComponent<IslandNavigator>();actor.transform.position=wood.approach;nav.ResetRoute();Require(actor.TryBegin(wood)&&!actors[2].TryBegin(wood),"Source reservation not exclusive");Require(!wood.tree.Available,"Creature can take reserved tree");var phase=actor.Current;actor.Tick(20,true);world.Advance(20,true);Require(actor.Current==phase&&world.State.Find(wood.id).remaining==12,"Pause progressed harvest");for(int n=0;n<2000&&actor.Current!=VillagerResourceGathering.Phase.Carry;n++)actor.Tick(.05f,false);Require(actor.Current==VillagerResourceGathering.Phase.Carry&&world.State.cargo[1].amount==3&&world.State.wood==0&&wood.tree.Harvested,"Tree not cut into finite cargo");var pending=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(pending.Valid(),"Cargo season roundtrip invalid");pending.Resources.Recover(1);Require(pending.Resources.Find(wood.id).remaining==12,"Pending save did not recover yield");actor.GetComponent<CarryItem>().held=true;actor.Tick(.1f,false);actor.GetComponent<CarryItem>().held=false;Require(!actor.Active&&wood.owner==null&&world.State.Find(wood.id).remaining==12&&world.State.wood==0,"Carried villager lost/duplicated cargo");
   Require(actor.TryBegin(wood),"Cannot resume collecting felled timber");for(int n=0;n<4000&&actor.Active;n++)actor.Tick(.05f,false);Require(!actor.Active&&world.State.wood==3&&world.State.deliveries==1&&world.State.Find(wood.id).remaining==9,"Native wood delivery failed");
   var wheat=world.sources.First(s=>s.kind==VillageResource.Wheat&&world.Available(s));actor.transform.position=wheat.approach;nav.ResetRoute();Require(actor.TryBegin(wheat),"Cannot harvest wheat");float before=world.State.wheat;for(int n=0;n<4000&&actor.Active;n++)actor.Tick(.05f,false);Require(!actor.Active&&Mathf.Abs(world.State.wheat-before-3)<.001f&&world.State.Find(wheat.id).remaining==9,"Native wheat delivery failed");world.Advance(30,false);Require(Mathf.Abs(world.State.wheat-before-2)<.001f,"Stored food did not feed villagers");Require(test.Valid(),"Final resource state invalid");
   world.State.wood=36;Require(!actor.TryBegin(wood),"Full store accepted reservation");Require(!actors.Any(a=>a.Active)&&world.sources.All(s=>s.owner==null),"Gathering stranded an owner");
   Debug.Log("BWVR_RESOURCE_RUNTIME_PASS: native tree cutting and grain harvesting; exclusive reservations; protected creature targets; visible cargo; pause; carried-worker interruption; pending save recovery; real store deliveries; stock consumption; capacity and cleanup");
  }finally{foreach(var actor in actors)actor.Cancel();field.SetValue(slice,original);world.ResetWorld();for(int i=0;i<actors.Length;i++){actors[i].transform.position=positions[i];actors[i].GetComponent<IslandNavigator>().ResetRoute();}}
 }
}
}
